from decimal import Decimal

import pytest

from payment.domain.money import Money


def test_zero_amount_is_rejected() -> None:
    with pytest.raises(ValueError, match="positive"):
        Money(Decimal("0"), "EUR")


def test_negative_amount_is_rejected() -> None:
    with pytest.raises(ValueError, match="positive"):
        Money(Decimal("-1"), "EUR")


def test_smallest_positive_amount_is_accepted() -> None:
    assert Money(Decimal("0.01"), "EUR").amount == Decimal("0.01")


@pytest.mark.parametrize("currency", ["", "   "])
def test_blank_currency_is_rejected(currency: str) -> None:
    with pytest.raises(ValueError, match="currency"):
        Money(Decimal("1"), currency)


def test_currency_is_normalized_to_upper_case() -> None:
    assert Money(Decimal("1"), "eur").currency == "EUR"
E
